// 共享占用采用/历史重放使用同一有限端点谓词；容量与身体/WIP保位证明始终反读原owner。
#include "facility_claims.hpp"
#include "facility_claims_candidate.hpp"
#include "resident/kernel/world_bundle.hpp"
#include <algorithm>
#include <limits>
#include <map>
#include <set>
#include <stdexcept>
namespace hanmo::resident {
namespace {
struct ClaimFailure { RuleError error; };
void fail(const char* code){RuleError e;e.original={code,"facility_claims"};throw ClaimFailure{std::move(e)};}
template<class T> T take(Outcome<T> r){if(!r.ok)throw ClaimFailure{std::move(r.error)};return std::move(r.value);}
template<class T,class F> Outcome<T> guard(F fn){try{return {true,fn(),{}};}catch(ClaimFailure& e){return {false,{},std::move(e.error)};}catch(const std::bad_alloc&){RuleError e;e.original={"FacilityClaimResourceExhausted","facility_claims"};e.kind=ErrorKind::internal;return {false,{},std::move(e)};}catch(const std::length_error&){RuleError e;e.original={"FacilityClaimResourceExhausted","facility_claims"};e.kind=ErrorKind::internal;return {false,{},std::move(e)};}}
int cmp(const WorldMoment& a,const WorldMoment& b,ExactArithmeticBudget x){return take(compare_world_moments(a,b,x));}
Integer sum(Integer a,Integer b){if(a<0||b<0||b>std::numeric_limits<Integer>::max()-a)fail("FacilityUnitsOverflow");return a+b;}
bool source_equal(const FacilitySourceRef& a,const FacilitySourceRef& b){return a.source_schema==b.source_schema&&same_source_ref(a.source_ref,b.source_ref);}
bool slot_valid(const FacilitySlotRef& s){return !s.provider_domain.empty()&&!s.facility_id.empty()&&!s.slot_kind.empty();}
bool selected(const FacilityClaimsCatalog& c,const FacilitySlotRef& slot){return std::find(c.selected_slots.begin(),c.selected_slots.end(),slot)!=c.selected_slots.end();}
const FacilitySlotHistory* history(const FacilityClaimsState& s,const FacilitySlotRef& slot){auto i=std::lower_bound(s.slot_histories.begin(),s.slot_histories.end(),slot,[](const auto& a,const auto& b){return a.slot_ref<b;});return i!=s.slot_histories.end()&&i->slot_ref==slot?&*i:nullptr;}
Integer revision(const FacilitySlotHistory* h){if(!h)return 0;if(!h->mutations.empty())return h->mutations.back().claim_set_revision;if(const auto* b=std::get_if<VacantPrunedFacilityPrefix>(&h->base))return b->last_removed_revision;return 0;}
bool same_claim(const FacilityClaim2& a,const FacilityClaim2& b,ExactArithmeticBudget budget){return a.claim_id==b.claim_id&&a.slot_ref==b.slot_ref&&a.holder==b.holder&&cmp(a.from,b.from,budget)==0&&cmp(a.until,b.until,budget)==0&&a.units==b.units&&a.capacity_revision==b.capacity_revision&&same_source_ref(a.usage_right_ref,b.usage_right_ref)&&same_source_ref(a.source_result_ref,b.source_result_ref);}
bool same_receipt(const FacilityClaimMutationReceipt& a,const FacilityClaimMutationReceipt& z,ExactArithmeticBudget b){if(a.claim_set_revision!=z.claim_set_revision||cmp(a.occurred_at,z.occurred_at,b)!=0||!same_source_ref(a.source_result_ref,z.source_result_ref)||a.source_schema!=z.source_schema||a.closed_claims.size()!=z.closed_claims.size()||a.admitted_claims.size()!=z.admitted_claims.size()||a.capacity_source_refs.size()!=z.capacity_source_refs.size())return false;for(std::size_t i=0;i<a.closed_claims.size();++i)if(a.closed_claims[i].claim_id!=z.closed_claims[i].claim_id||a.closed_claims[i].reason!=z.closed_claims[i].reason)return false;for(std::size_t i=0;i<a.admitted_claims.size();++i)if(!same_claim(a.admitted_claims[i],z.admitted_claims[i],b))return false;for(std::size_t i=0;i<a.capacity_source_refs.size();++i)if(!source_equal(a.capacity_source_refs[i],z.capacity_source_refs[i]))return false;return true;}
void source_refs(const std::vector<FacilitySourceRef>& refs){std::set<std::tuple<StableId,StableId,StableId,Integer>> seen;for(const auto& r:refs)if(!valid_source_ref(r.source_ref)||r.source_schema<=0||!seen.emplace(r.source_ref.domain,r.source_ref.kind,r.source_ref.id,r.source_schema).second)fail("InvalidFacilityCapacityReference");}
// 端点集合来自真实claim和provider分段；同点结束先于开始由半开成员谓词自然保证。
struct CapacitySweep { Integer minimum_available=std::numeric_limits<Integer>::max(); Integer newest_revision=0; };
CapacitySweep sweep(const FacilitySlotRef& slot,const std::vector<const FacilityClaim2*>& claims,const std::vector<FacilitySourceRef>& refs,const MomentSpan& requested,const FacilityClaimSourceRead& reader,ExactArithmeticBudget b){
    if(cmp(requested.from,requested.to,b)>=0)fail("InvalidFacilitySweepWindow");source_refs(refs);if(refs.empty())fail("MissingFacilityCapacitySources");
    std::vector<VerifiedFacilityCapacitySegment> segments;std::vector<WorldMoment> endpoints{requested.from,requested.to};
    for(const auto& ref:refs){auto parts=take(reader.read_verified_capacity(ref,slot,requested));for(auto& p:parts){if(p.source.slot_ref!=slot||p.source.capacity<0||p.source.capacity_revision<=0||p.source.capacity_unit_id.empty()||p.source.place_ref.empty()||!valid_source_ref(p.source.source_fact_ref)||!valid_source_ref(p.source.usage_right_ref)||cmp(p.window.from,p.window.to,b)>=0)fail("InvalidFacilityCapacitySegment");if(!same_source_ref(p.source.source_fact_ref,ref.source_ref))fail("FacilityCapacitySourceMismatch");if(cmp(p.window.to,requested.from,b)<=0||cmp(p.window.from,requested.to,b)>=0)continue;endpoints.push_back(cmp(p.window.from,requested.from,b)<0?requested.from:p.window.from);endpoints.push_back(cmp(p.window.to,requested.to,b)>0?requested.to:p.window.to);for(const auto& open:p.source.availability_intervals){if(cmp(open.from,open.to,b)>=0)fail("InvalidFacilityAvailabilityWindow");if(cmp(open.from,requested.from,b)>0&&cmp(open.from,requested.to,b)<0)endpoints.push_back(open.from);if(cmp(open.to,requested.from,b)>0&&cmp(open.to,requested.to,b)<0)endpoints.push_back(open.to);}segments.push_back(std::move(p));}}
    for(const auto* c:claims){if(c->slot_ref!=slot)fail("WrongFacilitySlot");if(cmp(c->from,requested.from,b)>0&&cmp(c->from,requested.to,b)<0)endpoints.push_back(c->from);if(cmp(c->until,requested.from,b)>0&&cmp(c->until,requested.to,b)<0)endpoints.push_back(c->until);}
    std::sort(endpoints.begin(),endpoints.end(),[&](const auto& a,const auto& z){return cmp(a,z,b)<0;});endpoints.erase(std::unique(endpoints.begin(),endpoints.end(),[&](const auto& a,const auto& z){return cmp(a,z,b)==0;}),endpoints.end());CapacitySweep result;
    for(std::size_t i=1;i<endpoints.size();++i){MomentSpan span{endpoints[i-1],endpoints[i]};const FacilityCapacitySource2* capacity=nullptr;for(const auto& seg:segments)if(cmp(seg.window.from,span.from,b)<=0&&cmp(span.to,seg.window.to,b)<=0){if(capacity)fail("OverlappingFacilityCapacitySegments");capacity=&seg.source;}if(!capacity)fail("FacilityCapacityCoverageGap");result.newest_revision=std::max(result.newest_revision,capacity->capacity_revision);
        std::vector<const FacilityClaim2*> occupied;for(const auto* c:claims)if(cmp(c->from,span.to,b)<0&&cmp(span.from,c->until,b)<0)occupied.push_back(c);
        bool available=false;for(const auto& open:capacity->availability_intervals)if(cmp(open.from,span.from,b)<=0&&cmp(span.to,open.to,b)<=0){available=true;break;}
        Integer normal=0,total=0;for(const auto* c:occupied){total=sum(total,c->units);const bool retained=take(reader.is_verified_retained_claim(*c,span,*capacity));if(!retained){normal=sum(normal,c->units);if(!available)fail("FacilityServiceOutsideAvailability");}}
        const auto tag=capacity->admission_disposition.index();if(tag==0){if(total!=normal||total>capacity->capacity)fail("FacilityCapacityExceeded");}else if(tag==1){const auto& d=std::get<NormalWithRetentions>(capacity->admission_disposition);source_refs(d.retention_source_refs);if(d.retention_source_refs.empty()||normal>capacity->capacity)fail("InvalidFacilityRetentionCapacity");}else if(tag==2){const auto& d=std::get<EntireSlotNoNewAdmission>(capacity->admission_disposition);source_refs(d.retention_source_refs);if(normal!=0||!valid_source_ref(d.whole_slot_restriction_source_ref)||d.whole_slot_restriction_source_schema<=0)fail("FacilitySlotClosed");}else fail("UnknownFacilityAdmissionDisposition");
        // 原provider复核IndependentUnits与AggregateOnly各自双预算、原位置和完整retention链。
        take(reader.validate_retention_and_physical_occupancy(slot,span,occupied,*capacity));Integer free=take(reader.read_additional_normal_capacity(slot,span,occupied,*capacity));if(free<0||free>capacity->capacity-normal)fail("InvalidFacilityAvailableCapacity");if(!available||tag==2)free=0;result.minimum_available=std::min(result.minimum_available,free);
    }if(result.minimum_available==std::numeric_limits<Integer>::max())fail("MissingFacilityCapacitySegment");return result;
}
using Live=std::map<StableId,const FacilityClaim2*>;
std::vector<const FacilityClaim2*> pointers(const Live& live){std::vector<const FacilityClaim2*> out;out.reserve(live.size());for(const auto& r:live)out.push_back(r.second);return out;}
// 每次采用核全部未来预约而非只核此刻已使用者，避免曾经超售后靠早关档案掩盖。
void mutation(const FacilitySlotRef& slot,const FacilityClaimMutationReceipt& r,Live& live,std::set<StableId>& global_ids,const FacilityClaimsCatalog& catalog,const FacilityClaimSourceRead& reader,ExactArithmeticBudget b){
    if(r.claim_set_revision<=0||r.source_schema<=0||!valid_source_ref(r.source_result_ref))fail("InvalidFacilityMutation");take(reader.validate_mutation_source(slot,r));source_refs(r.capacity_source_refs);StableId previous;
    for(const auto& close:r.closed_claims){if(close.claim_id.empty()||(!previous.empty()&&close.claim_id<=previous)||static_cast<unsigned>(close.reason)>7)fail("InvalidFacilityCloseOrder");previous=close.claim_id;auto i=live.find(close.claim_id);if(i==live.end())fail("FacilityClaimAlreadyClosed");take(reader.validate_claim_close(*i->second,close.reason,r));live.erase(i);}
    for(const auto& c:r.admitted_claims){take(validate_facility_claim_value(c,catalog,b));if(c.slot_ref!=slot||cmp(c.from,r.occurred_at,b)<0||!same_source_ref(c.source_result_ref,r.source_result_ref)||!global_ids.insert(c.claim_id).second)fail("InvalidFacilityAdmission");take(reader.validate_claim_admission(c,r));if(!live.emplace(c.claim_id,&c).second)fail("DuplicateFacilityClaim");}
    if(r.closed_claims.empty()&&r.admitted_claims.empty()&&live.empty())fail("EmptyFacilityMutation");
    if(!live.empty()){WorldMoment end=r.occurred_at;for(const auto& row:live){if(cmp(row.second->until,r.occurred_at,b)<0)fail("ExpiredActiveFacilityClaim");if(cmp(end,row.second->until,b)<0)end=row.second->until;}if(cmp(r.occurred_at,end,b)<0)sweep(slot,pointers(live),r.capacity_source_refs,{r.occurred_at,end},reader,b);}
}
// 变更链完整覆盖真实base至稳定存档；同M各revision逐项反查其对应reconcile，不按时刻合并。
void changes(const FacilitySlotRef& slot,const FacilitySlotHistory* h,const WorldMoment& start,const WorldMoment& current,const FacilityCapacityChange& base,const FacilityClaimSourceRead& reader,ExactArithmeticBudget b){
    auto chain=take(reader.enumerate_capacity_changes(slot,start,current));FacilityCapacityChange previous=base;
    Live before;std::size_t cursor=0;const FacilityClaimMutationReceipt* last_consumed=nullptr;
    auto apply_original=[&](const FacilityClaimMutationReceipt& receipt){for(const auto& closed:receipt.closed_claims)before.erase(closed.claim_id);for(const auto& admitted:receipt.admitted_claims)before[admitted.claim_id]=&admitted;last_consumed=&receipt;};
    auto order_at=[&](const FacilityClaimMutationReceipt& receipt,const FacilityCapacityChange& event){const auto order=take(reader.compare_mutation_to_capacity_change(slot,receipt,event));const auto time=cmp(receipt.occurred_at,event.occurred_at,b);if((time<0&&order!=FacilityMutationCapacityOrder::before)||(time>0&&order!=FacilityMutationCapacityOrder::after)||(order==FacilityMutationCapacityOrder::reconciles&&time!=0))fail("FacilityCapacityAdoptionOrderMismatch");return order;};
    for(const auto& event:chain){
        if(event.revision<=0||event.source.source_schema<=0||!valid_source_ref(event.source.source_ref)||cmp(event.occurred_at,start,b)<0||cmp(event.occurred_at,current,b)>0)fail("InvalidFacilityCapacityChange");
        // inclusive枚举可重遇基底；同M更晚revision继续按真实前驱逐项处理。
        if(event.revision<=base.revision){if(event.revision==base.revision&&!source_equal(event.source,base.source))fail("FacilityCapacityBaseMismatch");continue;}
        if(event.revision<=previous.revision||cmp(event.occurred_at,previous.occurred_at,b)<0||!event.previous_source||!source_equal(*event.previous_source,previous.source))fail("FacilityCapacityChangeGap");previous=event;
        if(last_consumed&&order_at(*last_consumed,event)!=FacilityMutationCapacityOrder::before)fail("FacilityCapacityAdoptionOrderMismatch");
        const FacilityClaimMutationReceipt* matched=nullptr;
        // 两条已核单调原链归并；每个mutation只消耗一次，不为每个capacity重放全国历史。
        if(h)while(cursor<h->mutations.size()){const auto& receipt=h->mutations[cursor];const auto order=order_at(receipt,event);if(order==FacilityMutationCapacityOrder::before){apply_original(receipt);++cursor;continue;}if(order==FacilityMutationCapacityOrder::reconciles)matched=&receipt;else if(order!=FacilityMutationCapacityOrder::after)fail("UnknownFacilityCapacityAdoptionOrder");break;}
        if(take(reader.source_change_affects_claims(event,pointers(before)))&&!matched)fail("MissingFacilityCapacityReconcile");
        if(matched){auto actual=take(reader.read_capacity_reconciliation_source(slot,event));if(!source_equal(actual,{matched->source_result_ref,matched->source_schema}))fail("FacilityCapacityReconcileSourceMismatch");bool capacity_bound=false;for(const auto& ref:matched->capacity_source_refs)if(source_equal(ref,event.source))capacity_bound=true;if(!capacity_bound)fail("MissingReconciledFacilityCapacitySource");apply_original(*matched);++cursor;if(h&&cursor<h->mutations.size()&&order_at(h->mutations[cursor],event)!=FacilityMutationCapacityOrder::after)fail("DuplicateFacilityCapacityReconcile");}
        // 零mutation/空claim仍读实际原source；不把表空解释为provider从未改变。
        if(cmp(event.occurred_at,current,b)<0)take(reader.read_verified_capacity(event.source,slot,{event.occurred_at,current}));
    }
    const auto actual=take(reader.capacity_source_at(slot,current));if(!source_equal(actual,previous.source))fail("FacilityCapacityChangeTailMissing");
}
}
Status validate_facility_claim_value(const FacilityClaim2& c,const FacilityClaimsCatalog& catalog,ExactArithmeticBudget b){return guard<Done>([&]{if(catalog.max_claim_half_days<=0||catalog.max_claim_half_days==std::numeric_limits<Integer>::max()||!slot_valid(c.slot_ref)||!selected(catalog,c.slot_ref)||c.claim_id.empty()||c.holder.empty()||c.units<=0||c.capacity_revision<=0||!valid_source_ref(c.usage_right_ref)||!valid_source_ref(c.source_result_ref)||c.from.half_day_tick<0||cmp(c.from,c.until,b)>=0)fail("InvalidFacilityClaim");auto length=take(elapsed_world_duration(c.from,c.until,b));auto maximum=take(normalize_fraction(std::to_string(catalog.max_claim_half_days),"1",b));if(take(compare_fractions(length.value,maximum,b))>0)fail("FacilityClaimWindowTooLong");return Done{};});}
static Status validate_claims_boundary(const FacilityClaimsState& s,const FacilityClaimsCatalog& catalog,const WorldMoment& current,const FacilityClaimSourceRead& reader,bool stable,ExactArithmeticBudget b){return guard<Done>([&]{take(encode_world_moment(current,b));if(catalog.max_claim_half_days<=0||catalog.max_claim_half_days==std::numeric_limits<Integer>::max())fail("InvalidFacilityClaimProfile");std::set<FacilitySlotRef> slots;for(const auto& slot:catalog.selected_slots)if(!slot_valid(slot)||!slots.insert(slot).second)fail("InvalidSelectedFacilitySlot");std::set<StableId> ids;std::map<StableId,const FacilityClaim2*> derived;std::optional<FacilitySlotRef> prior;
    for(const auto& h:s.slot_histories){if(!selected(catalog,h.slot_ref)||(prior&&!( *prior<h.slot_ref)))fail("InvalidFacilityHistoryOrder");prior=h.slot_ref;}
    for(const auto& slot:catalog.selected_slots){const auto* h=history(s,slot);auto start=take(reader.initial_source_at(slot));Integer rev=0;if(h)if(const auto* base=std::get_if<VacantPrunedFacilityPrefix>(&h->base)){if(base->last_removed_revision<=0||base->last_close_source_schema<=0||!valid_source_ref(base->last_close_result_ref)||cmp(base->cut_at,start,b)<0)fail("InvalidFacilityPrunedBase");take(reader.validate_pruned_prefix(slot,*base));rev=base->last_removed_revision;start=base->cut_at;}if(cmp(start,current,b)>0)fail("FacilityHistoryStartsInFuture");auto base=take(reader.read_capacity_history_base(slot,h?h->base:FacilityHistoryBase{InitialEmptyFacilityClaims{}}));if(!valid_source_ref(base.source.source_ref)||base.source.source_schema<=0||base.revision<=0||cmp(base.occurred_at,start,b)>0)fail("MissingInitialFacilityCapacitySource");if(cmp(start,current,b)<0)take(reader.read_verified_capacity(base.source,slot,{start,current}));Live live;WorldMoment at=start;std::map<StableId,std::pair<Integer,std::optional<Integer>>> episodes;
        if(h)for(const auto& r:h->mutations){if(rev==std::numeric_limits<Integer>::max()||r.claim_set_revision!=rev+1||cmp(r.occurred_at,at,b)<0||cmp(r.occurred_at,current,b)>0)fail("FacilityMutationSequenceMismatch");mutation(slot,r,live,ids,catalog,reader,b);for(const auto& admitted:r.admitted_claims)episodes.emplace(admitted.claim_id,std::make_pair(r.claim_set_revision,std::optional<Integer>{}));for(const auto& closed:r.closed_claims){auto found=episodes.find(closed.claim_id);if(found==episodes.end()||found->second.second)fail("InvalidFacilityClaimClose");found->second.second=r.claim_set_revision;}rev=r.claim_set_revision;at=r.occurred_at;}
        changes(slot,h,start,current,base,reader,b);auto deps=take(reader.enumerate_claim_dependencies(slot));for(const auto& dep:deps){const auto found=episodes.find(dep.claim_id);if(dep.claim_id.empty()||found==episodes.end())fail("MissingFacilityClaimDependency");if(dep.receipt&&(dep.receipt->slot_ref!=slot||dep.receipt->claim_set_revision<=0||dep.receipt->claim_set_revision>rev||(dep.receipt->claim_set_revision!=found->second.first&&(!found->second.second||dep.receipt->claim_set_revision!=*found->second.second))))fail("InvalidFacilityReceiptDependency");}
        for(const auto& row:live){if(cmp(row.second->until,current,b)<0||(stable&&cmp(row.second->until,current,b)==0))fail("UnconsumedFacilityClaimDue");derived.emplace(row.first,row.second);}
        // 尾段即使没有新mutation也核当前及未来承诺，当前capacity恢复不能遮蔽changes反查。
        if(!live.empty()){WorldMoment end=current;for(const auto& row:live)if(cmp(end,row.second->until,b)<0)end=row.second->until;auto source=take(reader.capacity_source_at(slot,current));if(cmp(current,end,b)<0)sweep(slot,pointers(live),{source},{current,end},reader,b);}
    }
    if(s.claims.size()!=derived.size())fail("FacilityActiveHistoryMismatch");std::set<StableId> active_ids;for(const auto& c:s.claims){take(validate_facility_claim_value(c,catalog,b));auto found=derived.find(c.claim_id);if(!active_ids.insert(c.claim_id).second||found==derived.end()||!same_claim(c,*found->second,b))fail("FacilityActiveHistoryMismatch");}return Done{};});}
// 同Moment多原owner逐项采用可短暂留下until==M；真正发布/冷读绝不保留该中间态。
Status validate_facility_claims(const FacilityClaimsState& state,const FacilityClaimsCatalog& catalog,const WorldMoment& current,const FacilityClaimSourceRead& reader,ExactArithmeticBudget budget){return validate_claims_boundary(state,catalog,current,reader,true,budget);}
Outcome<FacilityClaimMutationReceipt> read_facility_claim_receipt(const FacilityClaimsState& s,const FacilityClaimReceiptRef& ref){return guard<FacilityClaimMutationReceipt>([&]{if(ref.claim_set_revision<=0)fail("InvalidFacilityReceiptRef");const auto* h=history(s,ref.slot_ref);if(!h)fail("MissingFacilityClaimReceipt");if(const auto* base=std::get_if<VacantPrunedFacilityPrefix>(&h->base))if(ref.claim_set_revision<=base->last_removed_revision)fail("FacilityClaimHistoryUnavailable");for(const auto& r:h->mutations)if(r.claim_set_revision==ref.claim_set_revision)return r;fail("MissingFacilityClaimReceipt");return FacilityClaimMutationReceipt{};});}
Outcome<FacilityClaimEpisode> read_facility_claim_episode(const FacilityClaimsState& s,const StableId& id,const WorldMoment& current,ExactArithmeticBudget b){return guard<FacilityClaimEpisode>([&]{std::optional<FacilityClaimEpisode> out;WorldMoment admitted,closed=current;for(const auto& h:s.slot_histories)for(const auto& r:h.mutations){for(const auto& c:r.admitted_claims)if(c.claim_id==id){if(out)fail("DuplicateFacilityClaimAdmission");out=FacilityClaimEpisode{{h.slot_ref,r.claim_set_revision},c,{},{}};admitted=r.occurred_at;}for(const auto& c:r.closed_claims)if(c.claim_id==id){if(!out||out->close_receipt_ref)fail("InvalidFacilityClaimClose");out->close_receipt_ref=FacilityClaimReceiptRef{h.slot_ref,r.claim_set_revision};closed=r.occurred_at;}}if(!out)fail("MissingFacilityClaimEpisode");auto from=cmp(out->original_claim.from,admitted,b)>0?out->original_claim.from:admitted;auto until=cmp(out->original_claim.until,closed,b)<0?out->original_claim.until:closed;if(cmp(from,until,b)<0)out->actual_reserved_span=MomentSpan{from,until};return *out;});}
Outcome<FacilityClaimQuote> quote_facility_claim(const FacilityClaimsState& s,const FacilityClaimsCatalog& catalog,const FacilityClaimRequest2& request,const std::vector<FacilitySourceRef>& refs,const WorldMoment& now,const FacilityClaimSourceRead& reader,ExactArithmeticBudget b){return guard<FacilityClaimQuote>([&]{if(cmp(request.from,now,b)<0||request.holder.empty()||request.units<=0||!valid_source_ref(request.usage_right_ref)||!selected(catalog,request.slot_ref))fail("InvalidFacilityRequest");std::set<StableId> replace;for(const auto& id:request.replace_claim_ids)if(id.empty()||!replace.insert(id).second)fail("DuplicateFacilityReplacement");std::vector<const FacilityClaim2*> live;FacilityClaimQuote q;q.requested=request;q.claim_set_revision=revision(history(s,request.slot_ref));for(const auto& c:s.claims)if(c.slot_ref==request.slot_ref){if(replace.erase(c.claim_id)){if(c.holder!=request.holder)fail("FacilityReplacementHolderMismatch");continue;}live.push_back(&c);if(cmp(c.from,request.until,b)<0&&cmp(request.from,c.until,b)<0&&take(reader.conflicting_source_visible(request.holder,c)))q.conflicting_visible_refs.push_back(c.source_result_ref);}if(!replace.empty())fail("MissingFacilityReplacement");auto checked=sweep(request.slot_ref,live,refs,{request.from,request.until},reader,b);q.minimum_available_units=checked.minimum_available;q.capacity_revision=checked.newest_revision;if(q.minimum_available_units<request.units)fail("FacilityCapacityUnavailable");auto duration=take(elapsed_world_duration(request.from,request.until,b));if(take(compare_fractions(duration.value,take(normalize_fraction(std::to_string(catalog.max_claim_half_days),"1",b)),b))>0)fail("FacilityClaimWindowTooLong");return q;});}
// 两个入口共用一份采用/校验逻辑；纯函数保完整副本，阶段口已由WorldBundle包住全部业务写。
static void mutate_claims(FacilityClaimsState& next,const FacilityClaimsCatalog& catalog,const FacilitySlotRef& slot,const FacilityClaimMutationReceipt& r,Integer expected,const WorldMoment& now,const FacilityClaimSourceRead& reader,ExactArithmeticBudget b){
    if(const auto* retained=history(next,slot))for(const auto& prior:retained->mutations)if(prior.claim_set_revision==r.claim_set_revision){if(!same_receipt(prior,r,b))fail("FacilityReceiptReplayPayloadMismatch");take(reader.validate_mutation_source(slot,prior));return;}
    if(revision(history(next,slot))!=expected||expected==std::numeric_limits<Integer>::max()||r.claim_set_revision!=expected+1||cmp(r.occurred_at,now,b)!=0)fail("StaleFacilityClaimRevision");
    auto hi=std::lower_bound(next.slot_histories.begin(),next.slot_histories.end(),slot,[](const auto& a,const auto& key){return a.slot_ref<key;});if(hi==next.slot_histories.end()||hi->slot_ref!=slot)hi=next.slot_histories.insert(hi,FacilitySlotHistory{slot,InitialEmptyFacilityClaims{},{}});
    hi->mutations.push_back(r);std::set<StableId> close;for(const auto& c:r.closed_claims)close.insert(c.claim_id);next.claims.erase(std::remove_if(next.claims.begin(),next.claims.end(),[&](const auto& c){return close.count(c.claim_id)!=0;}),next.claims.end());for(const auto& c:r.admitted_claims)next.claims.push_back(c);
    take(validate_claims_boundary(next,catalog,now,reader,false,b));
}
Outcome<FacilityClaimsState> apply_facility_claim_mutation(const FacilityClaimsState& s,const FacilityClaimsCatalog& catalog,const FacilitySlotRef& slot,const FacilityClaimMutationReceipt& r,Integer expected,const WorldMoment& now,const FacilityClaimSourceRead& reader,ExactArithmeticBudget b){return guard<FacilityClaimsState>([&]{FacilityClaimsState next=s;mutate_claims(next,catalog,slot,r,expected,now,reader,b);return next;});}
Status adopt_facility_claim_mutation_in_candidate(WorldBundle& world,const FacilityClaimsCatalog& catalog,const FacilitySlotRef& slot,const FacilityClaimMutationReceipt& receipt,Integer expected,const WorldMoment& at,const FacilityClaimSourceRead& source,ExactArithmeticBudget budget){return guard<Done>([&]{
    if(!world.catalog||!world.facility_claims||!world.world_timeline||!world.catalog->exact_time||!exact_complete_selected(*world.catalog->exact_time))fail("FacilityCandidateRootRequired");
    if(cmp(take(world.actual_phase_moment()),at,budget)!=0)fail("FacilityCandidatePhaseMomentMismatch");
    struct Boundary {WorldBundle& world;explicit Boundary(WorldBundle& w):world(w){world.note_write_boundary();}~Boundary(){world.note_write_boundary();}} boundary(world);
    mutate_claims(*world.facility_claims,catalog,slot,receipt,expected,at,source,budget);return Done{};
});}
Outcome<FacilityClaimsState> prune_vacant_facility_prefix(const FacilityClaimsState& s,const FacilityClaimsCatalog& catalog,const FacilitySlotRef& slot,Integer through,const WorldMoment& now,const FacilityClaimSourceRead& reader,ExactArithmeticBudget b){return guard<FacilityClaimsState>([&]{take(validate_facility_claims(s,catalog,now,reader,b));const auto* h=history(s,slot);if(!h)fail("MissingFacilityHistory");Live live;const FacilityClaimMutationReceipt* cut=nullptr;std::set<StableId> removed;for(const auto& r:h->mutations){if(r.claim_set_revision>through)break;for(const auto& c:r.closed_claims)live.erase(c.claim_id);for(const auto& c:r.admitted_claims){live[c.claim_id]=&c;removed.insert(c.claim_id);}if(r.claim_set_revision==through)cut=&r;}if(!cut||!live.empty()||cut->closed_claims.empty())fail("FacilityPruneRequiresVacantClose");for(const auto& dep:take(reader.enumerate_claim_dependencies(slot)))if(removed.count(dep.claim_id)||(dep.receipt&&dep.receipt->claim_set_revision<=through))fail("FacilityHistoryPinned");VacantPrunedFacilityPrefix base{through,cut->occurred_at,cut->source_result_ref,cut->source_schema};take(reader.validate_pruned_prefix(slot,base));FacilityClaimsState next=s;for(auto& entry:next.slot_histories)if(entry.slot_ref==slot){entry.base=base;entry.mutations.erase(entry.mutations.begin(),std::find_if(entry.mutations.begin(),entry.mutations.end(),[&](const auto& r){return r.claim_set_revision>through;}));}take(validate_facility_claims(next,catalog,now,reader,b));return next;});}
}
